  if(!school&&page==='training'&&!org.people.length)return <><PageHeader title={t('Department progress','部门实施进度','Kemajuan jabatan')} description={t('Department-level implementation status is tracked on the overview. Individual training checkpoints need optional employee profiles.','部门级实施状态请在概览页手动记录；员工培训阶段需要可选的员工资料。','Status pelaksanaan jabatan dijejak pada gambaran keseluruhan. Semakan latihan individu memerlukan profil pekerja pilihan.')}/><EmptyState title={t('No employee profiles added','尚未添加员工资料','Tiada profil pekerja')} description={t('You can keep working with department summaries, or add anonymous profiles if you need individual training plans.','可以继续使用部门摘要；若要制定个人培训计划，再添加匿名员工资料。','Anda boleh teruskan dengan ringkasan jabatan atau tambah profil tanpa nama untuk pelan latihan individu.')} action={<ButtonLink secondary to="/organization/hr/dashboard">{t('Back to department overview','返回部门概览','Kembali ke gambaran jabatan')}</ButtonLink>}/></>;
